-- Baseline schema generated by Modux from the model.
-- This is the V1 migration: it is applied once and is immutable. Later model changes
-- produce new V{n} migrations (a hand-edited applied migration breaks Flyway's checksum).

CREATE SEQUENCE IF NOT EXISTS purchase_sequence START WITH 1 INCREMENT BY 1;
CREATE TABLE IF NOT EXISTS purchase_entity (
    id bigint PRIMARY KEY,
    col_concert_id varchar(255),
    col_customer varchar(255),
    col_tickets integer,
    col_amount numeric(19, 4),
    col_card varchar(255),
    col_status varchar(255),
    col_reference integer,
    col_confirmed_by varchar(255),
    col_reason varchar(255)
);

CREATE SEQUENCE IF NOT EXISTS purchase_event_sequence START WITH 1 INCREMENT BY 1;
CREATE TABLE IF NOT EXISTS purchase_event (
    id bigint PRIMARY KEY,
    aggregate_id varchar(255),
    sequence_number bigint,
    event_type varchar(255),
    payload text,
    occurred_at timestamp,
    recorded_by varchar(255)
);

CREATE TABLE IF NOT EXISTS concert_view_read_model_entity (
    id varchar(255) PRIMARY KEY,
    col_artist varchar(255),
    col_venue varchar(255),
    col_date date,
    col_capacity integer,
    col_price numeric(19, 4),
    col_status varchar(255),
    col_zones text,
    col_description text
);

CREATE TABLE IF NOT EXISTS sales_sequence (
    name varchar(255) PRIMARY KEY,
    last_value bigint
);

CREATE SEQUENCE IF NOT EXISTS modux_inbox_sequence START WITH 1 INCREMENT BY 1;
CREATE TABLE IF NOT EXISTS modux_inbox (
    id bigint PRIMARY KEY,
    subscription_name varchar(255),
    message_hash varchar(64),
    processed_at timestamp
);

CREATE SEQUENCE IF NOT EXISTS modux_outbox_sequence START WITH 1 INCREMENT BY 1;
CREATE TABLE IF NOT EXISTS modux_outbox (
    id bigint PRIMARY KEY,
    destination varchar(255),
    payload text,
    created_at timestamp
);
